def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Prefix sums let us test each rectangle efficiently.
    colors = set(x for row in grid for x in row if x != bg)
    pref = {}
    for color in colors | {bg}:
        p = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                p[r + 1][c + 1] = (
                    p[r][c + 1] + p[r + 1][c] - p[r][c]
                    + (grid[r][c] == color)
                )
        pref[color] = p

    def rect_sum(p, r1, c1, r2, c2):
        return p[r2][c2] - p[r1][c2] - p[r2][c1] + p[r1][c1]

    best = [[-1] * w for _ in range(h)]
    result = [[bg] * w for _ in range(h)]

    for r1 in range(h):
        for r2 in range(r1 + 2, h + 1):
            for c1 in range(w):
                for c2 in range(c1 + 2, w + 1):
                    area = (r2 - r1) * (c2 - c1)
                    if rect_sum(pref[bg], r1, c1, r2, c2) != 0:
                        continue
                    for color in colors:
                        count = rect_sum(pref[color], r1, c1, r2, c2)
                        if count * 100 < area * 78:
                            continue
                        score = count
                        for r in range(r1, r2):
                            for c in range(c1, c2):
                                if score > best[r][c]:
                                    best[r][c] = score
                                    result[r][c] = color

    return result
